const BubbleHistogram& bubble_histogram_counts(const std::string&id,bool scale){
if(id=="L4E3G18")return scale?histogram_L4E3G18_child_scale:histogram_L4E3G18_child_pair;
if(id=="L4E3G211")return scale?histogram_L4E3G211_child_scale:histogram_L4E3G211_child_pair;
if(id=="L4E3G319")return scale?histogram_L4E3G319_child_scale:histogram_L4E3G319_child_pair;
if(id=="L4E3G372")return scale?histogram_L4E3G372_child_scale:histogram_L4E3G372_child_pair;
if(id=="L4E3G53")return scale?histogram_L4E3G53_child_scale:histogram_L4E3G53_child_pair;
if(id=="L4E3G69")return scale?histogram_L4E3G69_child_scale:histogram_L4E3G69_child_pair;
if(id=="L4E3G91")return scale?histogram_L4E3G91_child_scale:histogram_L4E3G91_child_pair;
if(id=="L4E3G94")return scale?histogram_L4E3G94_child_scale:histogram_L4E3G94_child_pair;
throw std::invalid_argument("untrained triangle child histogram");}

BubbleMappedPoint bubble_histogram_map(const std::string&id,bool scale,const std::array<Real,9>&p){
 const auto&model=bubble_histogram_counts(id,scale);BubbleMappedPoint out;out.jacobian=1;
 for(int axis=0;axis<9;++axis){long cumulative=0;bool found=false;
  for(int bin=0;bin<model.bins;++bin){long mass=model.counts[axis][bin];Real upper=Real(cumulative+mass)/65536;
   if(arb_lt(p[axis].v,upper.v)){Real slope=Real(65536)/Real(long(model.bins)*mass);out.point[axis]=Real(bin)/Real(model.bins)+(p[axis]-Real(cumulative)/65536)*slope;out.jacobian=out.jacobian*slope;found=true;break;}
   Real distance=p[axis]-upper;if(!arb_is_nonnegative(distance.v))throw std::runtime_error("uncertain exact histogram cell");cumulative+=mass;}
  if(!found)throw std::invalid_argument("strict triangle histogram cube required");pos(out.point[axis],"positive mapped coordinate");pos(1-out.point[axis],"mapped coordinate below one");}
 pos(out.jacobian,"positive complete histogram Jacobian");return out;
}
Real bubble_child_histogram_value(const BubbleTwoHostGraph&g,bool positive,bool scale,const std::array<Real,9>&p){
 auto m=bubble_histogram_map(g.id,scale,p);return m.jacobian*bubble_two_host_value(g,positive,scale,m.point);
}

